test("gemma4 chat stop tokens: an asset missing a spelling fails loudly", () => {
  // Letting a thinned set through gives the shape "does not stop at `<turn|>` and starts writing
  // the next turn itself", with not a single exception (a silent degradation only a golden notices).
  const assets = assetsOf(fixture);
  const thinned = new Map(assets.addedTokens);
  thinned.delete("<|tool_response>");
  assertThrows(
    () => gemma4StopTokens(new Tokenizer({ ...assets, addedTokens: thinned })),
    Error,
    "<|tool_response>",
  );
});

// ---- the types of input-caused failures (ADR 0107) ----------------------------------------
//
// The only way a host that carries several families (an HTTP server, a CLI, a UI) can tell a 400
// from a 500 is a single `instanceof`. Reading the message string would break silently the moment
// the wording is fixed. What this binds is **both sides of the line**; one side alone would let
// both "make everything a ModelInputError" and "make nothing a ModelInputError" through.

describe("gemma4 chat failure types (split by where the caller branches)", () => {
  it("a rejection of a request that cannot be accepted as such is caught as ModelInputError", () => {
    assertThrows(() => renderGemma4Chat([]), ModelInputError, "the conversation is empty");
    assertThrows(
      () => renderGemma4ChatTurn({ role: "assistant", content: "…" }),
      ModelInputError,
      "'assistant' cannot be a delta",
    );
  });

  it("an asset mismatch is not a ModelInputError (fixing the input does not fix it)", () => {
    // A stop-token spelling missing from the asset is a gap in the distribution, and the caller
    // rewriting the request does not get it through. Mixing it into 400 would leave users
    // suspecting their own input forever.
    const assets = assetsOf(fixture);
    const thinned = new Map(assets.addedTokens);
    thinned.delete("<|tool_response>");
    const error = assertThrows(
      () => gemma4StopTokens(new Tokenizer({ ...assets, addedTokens: thinned })),
      Error,
      "<|tool_response>",
    );
    assert(
      !(error instanceof ModelInputError),
      `an asset mismatch is mixed into the input-caused failures: ${error.message}`,
    );
  });
});

// ---- stop strings and collect-all (the chat layer — ADR 0083 addendum 2026-09-02) ----------
//
// The stop conditions split into two layers: **tokens** in the sequence layer (the checks of
// `generation_sequence_test.ts`), and **strings**, which can only be decided after decoding = in
// the chat layer (one stop string can split over several tokens, and one token can straddle the
// end of a stop string and the following text). What this binds is the chat-layer side, whose
// substance is `decodeChatChunks` (`src/gemma/pipeline.ts`) + `createStopStringFilter`
// (`src/text/detokenizer.ts`). So that the test decides the id → spelling mapping, the decoder is
// built from a real `StreamingDetokenizer` with **the fixture's spelling table**
// (`DetokenizerSource`) plugged in — without control over how tokens split, "a stop string across
// a boundary" cannot be reproduced.

/** The id → spelling table (`undefined` = a special token to skip). byte_fallback is given through `bytes`. */
const sourceOf = (
  spellings: readonly string[],
  bytes: Readonly<Record<number, number>> = {},
): DetokenizerSource => ({
  byteOf: (id) => (Object.hasOwn(bytes, id) ? bytes[id] : undefined),
  textOf: (id) => {
    assert(id < spellings.length, `the test's spelling table has no id ${id}`);
    return spellings[id];
  },
});

/** A token event sequence whose "how far it was drained" can be observed (to see how an early exit is folded). */
const fakeEvents = (ids: readonly number[]) => {
  const state = { emitted: 0, exhausted: false, closed: false };
  const events = (async function* (): AsyncGenerator<GenerationEvent, void, undefined> {
    try {
      yield { kind: "prefill", chunk: 1, chunks: 1 };
      for (const [index, id] of ids.entries()) {
        state.emitted += 1;
        yield { kind: "token", id, position: index };
      }
      state.exhausted = true;
    } finally {
      // Runs on `return()` (= an early exit) as well as on normal completion. Together with `exhausted` it reads as "folded midway".
      state.closed = true;
    }
  })();
  return { events, state };
};

/** One chat-layer decode (it also receives the returned stop string, so `for await` is not used). */
const decodeChat = async (
  spellings: readonly string[],
  ids: readonly number[],
  stopStrings: readonly string[],
  bytes: Readonly<Record<number, number>> = {},
): Promise<{
  readonly parts: string[];
  readonly matched: string | undefined;
  readonly state: { emitted: number; exhausted: boolean; closed: boolean };
}> => {
  const { events, state } = fakeEvents(ids);
  const chunks = decodeChatChunks(
    events,
    new StreamingDetokenizer(sourceOf(spellings, bytes)),
    createStopStringFilter(stopStrings),
  );
  const parts: string[] = [];
  for (;;) {
    const step = await chunks.next();
    if (step.done) return { parts, matched: step.value, state };
    parts.push(step.value);
  }
};

/** Spelling table: 0..3 have "Hello " + the stop string "END" appearing **across a token boundary**. */
const SPELLINGS = ["Hel", "lo ", "EN", "D!", "X!", " tail"];

test("chat stop strings: it stops even across a token boundary, and the stop string is not in the output", async () => {
  // "END" split into the two tokens "EN" and "D!". A shape that can only be decided on the decoded text.
  const { parts, matched, state } = await decodeChat(SPELLINGS, [0, 1, 2, 3, 5], ["END"]);
  assertEquals(matched, "END", "the matched stop string");
  assertEquals(
    parts.join(""),
    "Hello ",
    "neither the stop string itself nor what follows is streamed",
  );
  assertEquals(parts.filter((part) => part === "").length, 0, "no empty chunks");
  // Consumption stops there (the remaining tokens were not requested) = the sequence's early exit is folded.
  assertEquals(state.emitted, 4, "drains only up to the token that settled the stop");
  assertEquals(
    state.exhausted,
    false,
    "the event sequence was drained to the end (it did not stop)",
  );
  assertEquals(
    state.closed,
    true,
    "the event sequence's return() was not called (the cleanup leaks)",
  );
});

test("chat stop strings: without a match the held part flows at the end (not a single character dropped)", async () => {
  // Holding is a delay for the decision, not a truncation of the output — if "D" does not follow "EN", everything comes out.
  const { parts, matched, state } = await decodeChat(SPELLINGS, [0, 1, 2, 4], ["END"]);
  assertEquals(matched, undefined, "it did not stop");
  assertEquals(parts.join(""), "Hello ENX!", "everything flows, including the held prefix");
  assertEquals(state.exhausted, true, "the event sequence is drained to the end");
});

test("chat stop strings: it holds only while the text is a prefix (it does not keep the rendering stalled)", async () => {
  // Checks even the **order** of the chunks (checking only the concatenation would let a fake
  // streaming that "emits everything at the end" through). It holds only while "EN" is a prefix of
  // the stop string, and flushes it together once it no longer matches.
  const { parts } = await decodeChat(SPELLINGS, [0, 1, 2, 4], ["END"]);
  assertEquals(
    parts,
    ["Hel", "lo ", "ENX!"],
    "held only while a prefix (catches up on the 3rd chunk)",
  );
  // A turn unrelated to the stop strings holds not a single character (each chunk flows as is).
  const bare = await decodeChat(SPELLINGS, [0, 1, 5], ["ZZZ"]);
  assertEquals(bare.parts, ["Hel", "lo ", " tail"]);
});

test("chat stop strings: the settled part of a byte run is decided too (it stops at the end of the sequence)", async () => {
  // A byte_fallback run does not settle until the next non-byte token or `finish()` (ADR 0084
  // decision 4). Without passing that settled part to the decision, a stop string completed
  // inside the run is missed.
  const spellings = ["Hi ", "EN", "<0x44>"];
  const { parts, matched } = await decodeChat(spellings, [0, 1, 2], ["END"], { 2: 0x44 });
  assertEquals(
    matched,
    "END",
    "the 'D' settled at the end of the sequence completes the stop string",
  );
  assertEquals(parts.join(""), "Hi ");
});

test("chat stop strings: an empty string and duplicates fail loudly", () => {
  // An empty string "always matches" = a setting that can emit not a single character, and a duplicate writes the same condition twice (both are mix-ups).
  assertThrows(() => createStopStringFilter([""]), Error, "stopStrings[0] is an empty string");
  assertThrows(
    () => createStopStringFilter(["END", "END"]),
    Error,
    'stopStrings contains "END" twice',
  );
});

test("chat stop strings: with several stop strings it cuts at the one that appears first in the text", async () => {
  // It carries **the one that actually cut the stream**, not the declaration order ("d" is declared first but "b" comes first in the text).
  const { parts, matched } = await decodeChat(["ab", "cd"], [0, 1], ["d", "b"]);
  assertEquals(matched, "b");
  assertEquals(parts.join(""), "a");
});

describe("chat stop strings: even with the stop reason replaced, the inner counts are copied (stopStringOf)", () => {
  // `chat` and `ChatSession.#finish` **rebuild `GenerationStop` into another object** only for a
  // turn closed by a stop string. If the rebuild drops a field the types still pass
  // (`speculation` is optional), so the shape "only turns closed by a stop string lose their
  // speculation counts" raises no exception.
  const speculation: GenerationSpeculation = {
    cycles: 4,
    draftRuns: 3,
    drafted: 9,
    accepted: 5,
    delivered: 9,
    acceptedHistogram: [1, 1, 1, 1],
  };

  it("a speculative turn: the counts are copied as they are (not recounted)", () => {
    const inner: GenerationStop = { reason: "max-tokens", tokens: 9, speculation };
    const stop = stopStringOf("END", inner);
    assertEquals(stop, { reason: "stop-string", stopString: "END", tokens: 9, speculation });
    assert(
      stop.speculation === speculation,
      "the counts were rebuilt (the inner value is not copied as is)",
    );
  });

  it("a non-speculative turn: the field itself is not added", () => {
    const stop = stopStringOf("END", { reason: "eos", token: 3, tokens: 4 });
    assertEquals(stop, { reason: "stop-string", stopString: "END", tokens: 4 });
    assertEquals(
      Object.hasOwn(stop, "speculation"),
      false,
      "a field was added to a non-speculative turn",
    );
    // The stop token (`token` of the `eos` branch) is replaced along with the reason, so it is not carried.
    assertEquals(Object.hasOwn(stop, "token"), false);
  });

  it("a run-ahead turn: the decodeAhead counters are copied as they are", () => {
    const decodeAhead = { depth: 4, batches: 2, steps: 7 };
    const stop = stopStringOf("END", { reason: "max-tokens", tokens: 8, decodeAhead });
    assertEquals(stop, { reason: "stop-string", stopString: "END", tokens: 8, decodeAhead });
    assert(stop.decodeAhead === decodeAhead, "the counters were rebuilt instead of copied");
    const plain = stopStringOf("END", { reason: "max-tokens", tokens: 8 });
    assertEquals(Object.hasOwn(plain, "decodeAhead"), false);
  });
});

test("speculative switch (speculativeSetup): passing true to a pipeline without a drafter fails loudly", () => {
  // Unset means "attach when a drafter is present", so without a drafter it is silently
  // non-speculative (no field added either). An explicit setting (`true` / `"always"`) requires a
  // drafter — running it silently non-speculative would leave the result no trace of being ignored.
  const withoutDrafter = { drafter: undefined, speculativeK: undefined };
  assertEquals(speculativeSetup(withoutDrafter, undefined), undefined);
  assertEquals(speculativeSetup(withoutDrafter, false), undefined);
  assertThrows(() => speculativeSetup(withoutDrafter, true), Error, "without a drafter");
  assertThrows(() => speculativeSetup(withoutDrafter, "always"), Error, "without a drafter");
});

// The drafter holds `session: Session` (a nominal type with `#` privates), so it cannot be
// satisfied structurally without a GPU. This check reads only the returned `policy` / `gate` and
// never calls `open`, so a fake that only fills the slot is plugged in (the same treatment
// `runtime/tests` gives the GPU objects).
const fakeDrafter = {} as unknown as Gemma4Drafter;

test("speculative gate knobs (speculativeSetup): they reach auto only, and always gets no field at all", () => {
  const knobs = { burstAbort: 10, burstMin: 8, exploreBase: 8 };
  const gated = { drafter: fakeDrafter, speculativeK: 2, speculativeGate: knobs };

  const auto = speculativeSetup(gated, true);
  assert(auto !== undefined, "no speculation attached although a drafter is present");
  assertEquals(auto.policy, "auto");
  // The same object is passed as is (a copy could make "the spelling passed to the pipeline" and
  // "the spelling the gate read" different things).
  assert(auto.gate === knobs, "the knobs were rebuilt");
  assertEquals(
    speculativeSetup(gated, undefined)?.gate,
    knobs,
    "they reach the default (unset = auto) too",
  );

  const always = speculativeSetup(gated, "always");
  assert(always !== undefined, "no speculation attached although a drafter is present");
  assertEquals(always.policy, "always");
  // `"always"` is the setting that builds no gate, so not adding the field at all is the spelling of
  // "this turn has no gate" (putting `undefined` there could not be told apart from "overrode the
  // default").
  assertEquals(
    Object.hasOwn(always, "gate"),
    false,
    "a gate field was added to a setting without a gate",
  );

  const ungated = speculativeSetup(
    { drafter: fakeDrafter, speculativeK: undefined, speculativeGate: undefined },
    true,
  );
  assert(ungated !== undefined);
  assertEquals(
    Object.hasOwn(ungated, "gate"),
    false,
    "a gate field was added with the knobs unset",
  );
});

test("speculative gate knobs: an invalid value fails before any weight is read (the argument check of fromPretrained)", async () => {
  // The **position** of the check is the subject of this test. `assertSpeculative` sits before the
  // interpretation of the source, so a wrong knob fails touching neither the network nor the GPU
  // (not the shape that fails only after a GB-scale load). The range decision itself is the check
  // on the gate side (`speculation-gate.ts`); this one confirms the pass-through.
  await assertRejects(
    () =>
      Pipeline.fromPretrained("karume/gemma4-e2b", {
        speculative: { gate: { burstAbort: 0 } },
      }),
    ModelInputError,
    "burstAbort 0 is not a positive finite number",
  );
  await assertRejects(
    () =>
      Pipeline.fromPretrained("karume/gemma4-e2b", {
        speculative: { gate: { burst: 8, burstMin: 9 } },
      }),
    ModelInputError,
    "burstMin 9 exceeds burst 8",
  );
  // The step count `k` is a caller setting of the same bundle, so it fails with the same type (ADR 0107 decision 2).
  await assertRejects(
    () => Pipeline.fromPretrained("karume/gemma4-e2b", { speculative: { k: 0 } }),
    ModelInputError,
    "speculative.k 0 is outside 1..",
  );
});

test("chat prefill: onPrefill receives the progress, and the text sequence does not change by a single character", async () => {
  // With a long prompt the silence until the first character is the prefill itself, and the string
  // surface has no chunk to carry its progress (not a single character of text has come out yet).
  // The observation hook is the only path.
  const events = (async function* (): AsyncGenerator<GenerationEvent, void, undefined> {
    yield { kind: "prefill", chunk: 1, chunks: 3 };
    yield { kind: "prefill", chunk: 2, chunks: 3 };
    yield { kind: "prefill", chunk: 3, chunks: 3 };
    yield { kind: "token", id: 0, position: 0 };
    yield { kind: "token", id: 1, position: 1 };
  })();
  const seen: { readonly chunk: number; readonly chunks: number }[] = [];
  const chunks = decodeChatChunks(
    events,
    new StreamingDetokenizer(sourceOf(SPELLINGS)),
    createStopStringFilter([]),
    (progress) => seen.push(progress),
  );
  const parts: string[] = [];
  for await (const part of chunks) parts.push(part);

  assertEquals(
    seen,
    [
      { chunk: 1, chunks: 3 },
      { chunk: 2, chunks: 3 },
      { chunk: 3, chunks: 3 },
    ],
    "the committed chunk count arrives as is",
  );
  assertEquals(
    parts,
    ["Hel", "lo "],
    "the text chunks do not change with or without the observation hook",
  );
});

test("chat collect-all: text() equals the concatenation of the chunks, and done can be read as well", async () => {
  const stop: ChatStop = { reason: "max-tokens", tokens: 3 };
  const chunks = (async function* (): AsyncGenerator<string, void, undefined> {
    yield "Hel";
    yield "lo ";
    yield "world";
  })();
  const stream = chatStreamOf(chunks, Promise.resolve(stop));
  assertEquals(await stream.text(), "Hello world");
  assertEquals(await stream.done, stop, "the stop reason can be read after text() too");
});

test("chat collect-all: one stream can be consumed in only one way (it fails synchronously)", async () => {
  const stop: ChatStop = { reason: "max-tokens", tokens: 1 };
  const streamOf = () =>
    chatStreamOf(
      (async function* (): AsyncGenerator<string, void, undefined> {
        yield "a";
      })(),
      Promise.resolve(stop),
    );
  // Generation runs only once, so the second way would get only "the rest" (a mix-up that raises no exception).
  const iterated = streamOf();
  for await (const _part of iterated) {
    /* drain to the end */
  }
  assertThrows(() => iterated.text(), Error, "can be consumed in only one way");

  const collected = streamOf();
  assertEquals(await collected.text(), "a");
  assertThrows(() => collected[Symbol.asyncIterator](), Error, "can be consumed in only one way");

  const twice = streamOf();
  twice[Symbol.asyncIterator]();
  assertThrows(() => twice[Symbol.asyncIterator](), Error, "can be consumed in only one way");
});

// ---- turn cleanup (`closeChatTurn`) -------------------------------------------------------
//
// If the serialization slot of `Pipeline.chat` were "not returned when the cleanup fails", the
// chain would never get the previous link's settlement and every later `chat` / `dispose` would
// wait forever (the path where `context.dispose` propagates a `flush` failure on device loss is
// real = a pipeline that never works again after one exception). Returning the slot and folding
// the exceptions are gathered in this one function, so the fault injection can be written here
// too (no GPU needed).

describe("chat cleanup: the slot is returned unconditionally, and a cleanup failure is carried together with the body's exception", () => {
  const failing = (error: unknown) => (): Promise<void> => Promise.reject(error);
  const caughtOf = (work: Promise<void>): Promise<unknown> =>
    work.then(
      () => undefined,
      (error: unknown) => error,
    );

  it("a successful cleanup only returns the slot", async () => {
    let released = 0;
    await closeChatTurn(
      "test",
      undefined,
      () => Promise.resolve(),
      () => {
        released += 1;
      },
    );
    assertEquals(released, 1);
  });

  it("the slot is returned even when the cleanup fails (the chain is not held)", async () => {
    const boom = new Error("context.dispose propagated a flush failure");
    let released = 0;
    const caught = await caughtOf(
      closeChatTurn("test", undefined, failing(boom), () => {
        released += 1;
      }),
    );
    assertEquals(caught, boom, "if the body succeeded, the cleanup's exception arrives as is");
    assertEquals(released, 1, "the slot is returned unconditionally");
  });

  it("if the body failed too, both are carried (neither fact is lost)", async () => {
    const body = new Error("turn body");
    const cleanup = new Error("cleanup");
    let released = 0;
    const caught = await caughtOf(
      closeChatTurn("test", { error: body }, failing(cleanup), () => {
        released += 1;
      }),
    );
    assert(caught instanceof AggregateError, `not an AggregateError: ${caught}`);
    assertEquals(caught.errors, [body, cleanup], "errors[0] is the body, errors[1] the cleanup");
    assertEquals(released, 1);
  });

  it("a caller without a slot (send) folds the same way", async () => {
    const body = new Error("turn body");
    const cleanup = new Error("cleanup");
    const caught = await caughtOf(closeChatTurn("test", { error: body }, failing(cleanup)));
    assert(caught instanceof AggregateError, `not an AggregateError: ${caught}`);
    assertEquals(caught.errors, [body, cleanup]);
  });
});

