// ---- tools, tool calls, tool results, thinking (ADR 0084 addendum 2026-11-04) ----------------
//
// The `toolChat` / `rejectedChat` / `responses` lists of both fixtures are harvested by
// `tools/export-recipes/gemma4/chat.py` from upstream `apply_chat_template` and
// `tokenizer.parse_response` (ADR 0084 decision 7 — independent of this renderer and parser).

/** Upstream's keyword arguments of one case (`apply_chat_template(..., **options)`). */
type UpstreamOptions = {
  readonly tools?: ChatTool[];
  readonly enable_thinking?: boolean;
  readonly preserve_thinking?: boolean;
};

type ToolChatRow = {
  readonly name: string;
  readonly why: string;
  readonly messages: ChatMessage[];
  readonly options: UpstreamOptions;
  readonly rendered: string;
  readonly ids: number[];
};

type RejectedRow = {
  readonly name: string;
  readonly why: string;
  readonly messages: unknown[];
  readonly options: UpstreamOptions;
  /** What upstream rendered (when it accepts the input). */
  readonly rendered?: string;
  /** What upstream raised (`Type: first line`). */
  readonly error?: string;
};

type ResponseRow = {
  readonly name: string;
  readonly why: string;
  readonly prefix: string;
  readonly text: string;
  readonly expect: "parse" | "upstream-raises" | "ts-rejects" | "blank-segment";
  /** `blank-segment` only: the output without its blank segment (what `parsed` is upstream's reading of). */
  readonly normalized?: string;
  readonly parsed?: ChatResponse;
  readonly error?: string;
  /** Upstream's result as a Python repr (`ts-rejects` only — documentation). */
  readonly upstream?: string;
};

type ToolFixture = Fixture & {
  readonly toolChat: ToolChatRow[];
  readonly rejectedChat: RejectedRow[];
  readonly responses: ResponseRow[];
};

/** Upstream's keyword arguments → the TS options object (camelCase — the maintainer's ruling). */
const optionsOf = (options: UpstreamOptions): ChatTemplateOptions => ({
  ...(options.tools === undefined ? {} : { tools: options.tools }),
  ...(options.enable_thinking === undefined ? {} : { enableThinking: options.enable_thinking }),
  ...(options.preserve_thinking === undefined
    ? {}
    : { preserveThinking: options.preserve_thinking }),
});

/** Why each `rejectedChat` input is refused (a stable fragment of the message). */
const REJECTION_REASONS: Readonly<Record<string, string>> = {
  "several-calls-without-ids": "the last call's name",
  "result-name-contradicts-call": "contradicts the call",
  "result-id-matches-no-call": "matches 0 of the calls",
  "orphan-tool-result": "follows no assistant message",
  "tool-calls-without-results": "no role 'tool' result follows",
  "tool-calls-awaiting-results": "no role 'tool' result follows",
  "tool-call-content-at-end": "its results end the conversation",
  "parameters-without-type": "no top-level type",
  "response-not-an-object": "is not an object schema",
  "response-null": "is not an object schema",
  "description-null": "Python's 'None'",
  "function-return": "function.return is not rendered",
  "speaker-name": "speaker name",
  "refusal-text": "does not render a refusal",
  "argument-string-with-delimiter": "cannot delimit",
  "argument-key-not-a-word": "is not a word",
  "result-name-of-no-call": "none of the turn's calls",
  "empty-result-name": "names no function",
  "arguments-as-string": "arguments is a string",
  "legacy-tool-responses": "tool_responses is out of scope",
  "content-parts": "content parts",
  "tool-result-object": "content is an object",
  "tool-name-not-a-word": "is not a word",
  "thinking-field": "does not read 'thinking'",
};

/** Why each `upstream-raises` / `ts-rejects` output is refused (a stable fragment of the message). */
const PARSE_REASONS: Readonly<Record<string, string>> = {
  "unterminated-string": "(opened in the output) is not closed",
  "bare-string-value": "not JSON",
  "stop-token-inside-call": "(opened in the output) is not closed",
  "empty-call-body": "not JSON",
  "space-before-key": "not JSON",
  "sentinel-character": "reserved characters",
  "hyphenated-name": "not JSON",
  "unterminated-call": "tool call get_weather (opened in the output) is not closed",
  "unterminated-thought": "thought channel (opened in the output) is not closed",
  "stop-token-inside-thought": "thought channel (opened in the output) is not closed",
  "no-stop-token": "is not closed by",
  "text-after-stop-token": "text follows the closing token",
  "content-overwritten": "more than one segment",
  "thought-overwritten": "two thought channels",
  "arguments-not-an-object": "are not an object",
  // NaN is not a JSON token, so it fails as syntax (the finiteness rule has its own rows).
  "non-finite-number": "not JSON",
  "call-without-name": "contains <|tool_call> outside its region",
  "integer-beyond-2-53": "beyond 2^53",
  "integer-of-400-digits": "which a double cannot hold",
  "float-beyond-double": "which a double cannot hold",
  "quoted-key-not-a-word": "is not a word",
  "next-turn-in-content": "contains <|turn> outside its region",
  "result-closer-in-content": "contains <tool_response|> outside its region",
  "delimiter-in-content": 'contains <|"|> outside its region',
  "prompt-without-anchor": "the prompt has no",
};

/** The reason a table names for a row (a row without one fails — every refusal states its why). */
const reasonOf = (table: Readonly<Record<string, string>>, name: string): string => {
  const reason = table[name];
  assert(reason !== undefined, `no reason is pinned for ${name}`);
  return reason;
};

const toolFixtures: readonly {
  readonly label: string;
  readonly dialect: ChatDialect;
  readonly fixture: ToolFixture;
  readonly tokenizer: Tokenizer;
}[] = [
  { label: "E2B", dialect: "gemma4", fixture: fixture as ToolFixture, tokenizer },
  {
    label: "12B",
    dialect: "gemma4-unified",
    fixture: fixture12b as ToolFixture,
    tokenizer: tokenizer12b,
  },
];

for (const { label, dialect, fixture: source, tokenizer: owner } of toolFixtures) {
  describe(`gemma4 ${label} tool chat rendering: equals upstream apply_chat_template`, () => {
    for (const row of source.toolChat) {
      it(`${row.name} — ${row.why}`, () => {
        assertEquals(renderGemma4Chat(row.messages, dialect, optionsOf(row.options)), row.rendered);
      });
    }
  });

  describe(`gemma4 ${label} tool chat ids: equal apply_chat_template(tokenize=True)`, () => {
    for (const row of source.toolChat) {
      it(`${row.name} — ${row.why}`, () => {
        assertEquals(chatPrompt(owner, row.messages, optionsOf(row.options)), row.ids);
      });
    }
  });

  describe(`gemma4 ${label} rejected input: fails loudly where upstream renders wrongly or raises`, () => {
    for (const row of source.rejectedChat) {
      it(`${row.name} — ${row.why}`, () => {
        // The rejection rests on what upstream was observed to do (one of the two is recorded).
        assert(
          (row.rendered === undefined) !== (row.error === undefined),
          "upstream's outcome is recorded",
        );
        assertThrows(
          () => renderGemma4Chat(row.messages as ChatMessage[], dialect, optionsOf(row.options)),
          ModelInputError,
          reasonOf(REJECTION_REASONS, row.name),
        );
      });
    }
  });

  describe(`gemma4 ${label} output parsing: equals upstream parse_response`, () => {
    for (const row of source.responses) {
      it(`${row.name} (${row.expect}) — ${row.why}`, () => {
        if (row.expect === "parse" || row.expect === "blank-segment") {
          // `blank-segment`: `parsed` is upstream's reading of the output without the blank
          // segment (upstream would let it erase the earlier text — its repr is in `upstream`).
          assertEquals(parseGemma4ChatResponse(row.text, row.prefix), row.parsed);
          return;
        }
        // `upstream-raises`: upstream raises too; `ts-rejects`: upstream returns data that would
        // hide a failure (its repr is in the fixture — the doc of `chat-response.ts` lists why).
        // The reason is pinned too: a throw for another reason would pass a bare assertThrows.
        assert((row.error ?? row.upstream) !== undefined, "upstream's outcome is recorded");
        assertThrows(
          () => parseGemma4ChatResponse(row.text, row.prefix),
          ModelInputError,
          reasonOf(PARSE_REASONS, row.name),
        );
      });
    }
  });
}

describe("gemma4 tool chat goldens discriminate (fault injection)", () => {
  const rows = (fixture as ToolFixture).toolChat;

  it("rendering without the case's options misses every golden that has options", () => {
    const optioned = rows.filter((row) => Object.keys(row.options).length > 0);
    assert(optioned.length >= 20, `only ${optioned.length} cases carry options`);
    for (const row of optioned) {
      let bare: string | undefined;
      try {
        bare = renderGemma4Chat(row.messages);
      } catch {
        bare = undefined;
      }
      assertNotEquals(bare, row.rendered, row.name);
    }
  });

  it("a parser that returns only the role matches no golden but the empty turn", () => {
    const parsed = (fixture as ToolFixture).responses.filter((row) => row.expect === "parse");
    const trivial = parsed.filter((row) => assertEqualsQuiet(row.parsed, { role: "assistant" }));
    assertEquals(
      trivial.map((row) => row.name),
      ["empty-turn"],
    );
    // Each field is pinned by several goldens.
    for (const field of ["content", "thinking", "tool_calls"] as const) {
      assert(
        parsed.filter((row) => row.parsed?.[field] !== undefined).length >= 3,
        `fewer than 3 goldens carry ${field}`,
      );
    }
  });
});

/** Deep equality as a boolean (for counting, not asserting). */
const assertEqualsQuiet = (left: unknown, right: unknown): boolean => {
  try {
    assertEquals(left, right);
    return true;
  } catch {
    return false;
  }
};

describe("gemma4 parseChatResponse: token ids in, special spellings kept", () => {
  const rows = (fixture as ToolFixture).responses.filter((row) => row.expect === "parse");

  it("decoding the encoded prompt and output gives upstream's result on every golden", () => {
    for (const row of rows) {
      assertEquals(
        parseChatResponse(tokenizer, tokenizer.encode(row.text), tokenizer.encode(row.prefix)),
        row.parsed,
        row.name,
      );
    }
  });

  it("the default decode (special tokens skipped) would lose the structure (fault injection)", () => {
    // `<|tool_call>` / `<|"|>` / `<turn|>` are special tokens — the text of a ChatStream drops them.
    const call = rows.find((row) => row.name === "one-call");
    assert(call !== undefined);
    const lossy = tokenizer.decode(tokenizer.encode(call.text));
    assertThrows(() => parseGemma4ChatResponse(lossy, call.prefix), ModelInputError, "not closed");
  });
});

describe("gemma4 chatToolResults: the delta after a tool call continues the model turn", () => {
  /** The model's canonical output for one assistant message (thought if rendered, then calls). */
  const canonicalOutput = (head: string, message: ChatAssistantMessage, gate: boolean): string => {
    const thought = message.reasoning || message.reasoning_content;
    const calls = (message.tool_calls ?? [])
      .map((call) => {
        const args = call.function.arguments ?? {};
        const body = Object.keys(args)
          .sort((a, b) => (a.toLowerCase() < b.toLowerCase() ? -1 : 1))
          .map((key) => `${key}:${JSON.stringify(args[key]).replaceAll('"', '<|"|>')}`)
          .join(",");
        return `<|tool_call>call:${call.function.name}{${body}}<tool_call|>`;
      })
      .join("");
    if (thought === undefined || thought === "" || !gate) return calls;
    // After a result with thinking on, the prompt already opened the channel.
    const open = head.endsWith("<|channel>thought\n") ? "" : "<|channel>thought\n";
    return `${open}${thought}\n<channel|>${calls}`;
  };

  // Cases whose model turn is a chain of calls answered by results (simple string arguments, so
  // the canonical spelling above is the template's).
  for (const name of [
    "tool-call-then-result",
    "tool-multi-step",
    "thinking-on-after-tool-result",
    "tool-calls-parallel-ids",
    "tool-call-single-without-ids",
  ]) {
    it(`${name}: whole render = prompt ⧺ call ⧺ <|tool_response> ⧺ results delta, at every step`, () => {
      const row = (fixture as ToolFixture).toolChat.find((candidate) => candidate.name === name);
      assert(row !== undefined, name);
      const options = optionsOf(row.options);
      const lastUser = row.messages.findLastIndex((message) => message.role === "user");
      let checked = 0;
      row.messages.forEach((message, index) => {
        if (message.role !== "assistant" || (message.tool_calls ?? []).length === 0) return;
        let end = index + 1;
        while (row.messages[end]?.role === "tool") end += 1;
        const head = renderGemma4Chat(row.messages.slice(0, index), "gemma4", options);
        const results = row.messages.slice(index + 1, end) as ChatToolMessage[];
        const grown = renderGemma4Chat(row.messages.slice(0, end), "gemma4", options);
        assertEquals(
          grown,
          head +
            canonicalOutput(head, message, index > lastUser) +
            "<|tool_response>" +
            renderGemma4ToolResults(message.tool_calls ?? [], results, options),
          `${name} step ${index}`,
        );
        // The same identity on token ids, with the stop token as the pending token.
        const stop = tokenizer.addedTokenId("<|tool_response>") as number;
        const generated = tokenizer.encode(canonicalOutput(head, message, index > lastUser));
        assertEquals(
          chatPrompt(tokenizer, row.messages.slice(0, end), options),
          [
            ...chatPrompt(tokenizer, row.messages.slice(0, index), options),
            ...generated,
            stop,
            ...chatToolResults(tokenizer, message.tool_calls ?? [], results, options),
          ],
          `${name} step ${index} (ids)`,
        );
        checked += 1;
      });
      assert(checked >= 1, `${name}: no tool-calling step was checked`);
    });
  }

  it("the delta starts after the pending <|tool_response>; further results open their own", () => {
    const calls: ChatToolCall[] = [
      { id: "a", type: "function", function: { name: "f", arguments: { x: 1 } } },
      { id: "b", type: "function", function: { name: "g", arguments: null } },
    ];
    const results: ChatToolMessage[] = [
      { role: "tool", tool_call_id: "b", content: "two" },
      { role: "tool", tool_call_id: "a", content: "one" },
    ];
    assertEquals(
      renderGemma4ToolResults(calls, results),
      'response:g{value:<|"|>two<|"|>}<tool_response|><|tool_response>response:f{value:<|"|>one<|"|>}<tool_response|>',
    );
    assertEquals(
      renderGemma4ToolResults(calls, results, { enableThinking: true }).endsWith(
        "<tool_response|><|channel>thought\n",
      ),
      true,
      "thinking on reopens the thought channel",
    );
  });

  it("results that cannot be resolved, or are not results, fail loudly", () => {
    const calls: ChatToolCall[] = [
      { type: "function", function: { name: "f", arguments: {} } },
      { type: "function", function: { name: "g", arguments: {} } },
    ];
    assertThrows(
      () => renderGemma4ToolResults(calls, [{ role: "tool", content: "x" }]),
      ModelInputError,
      "the last call's name",
    );
    assertThrows(() => renderGemma4ToolResults(calls, []), ModelInputError, "no results");
    assertThrows(
      () => renderGemma4ToolResults([], [{ role: "tool", content: "x" }]),
      ModelInputError,
    );
    assertThrows(
      () =>
        renderGemma4ToolResults(calls.slice(0, 1), [
          { role: "user", content: "x" } as unknown as ChatToolMessage,
        ]),
      ModelInputError,
      "not 'tool'",
    );
  });

  it("chatTurn refuses a tool message and points at chatToolResults", () => {
    assertThrows(
      () => renderGemma4ChatTurn({ role: "tool", content: "x" }),
      ModelInputError,
      "chatToolResults",
    );
  });

  it("a user delta ends with the 12B empty thought only while thinking is off", () => {
    const message: ChatMessage = { role: "user", content: "hi" };
    assertEquals(
      renderGemma4ChatTurn(message, "gemma4-unified"),
      "\n<|turn>user\nhi<turn|>\n<|turn>model\n<|channel>thought\n<channel|>",
    );
    assertEquals(
      renderGemma4ChatTurn(message, "gemma4-unified", { enableThinking: true }),
      "\n<|turn>user\nhi<turn|>\n<|turn>model\n",
    );
  });
});

describe("gemma4 chat options and declarations: the accepted set", () => {
  const user: ChatMessage[] = [{ role: "user", content: "hi" }];
  const reject = (label: string, options: unknown, expected: string): void => {
    it(label, () => {
      assertThrows(
        () => renderGemma4Chat(user, "gemma4", options as ChatTemplateOptions),
        ModelInputError,
        expected,
      );
    });
  };

  reject(
    "an unknown option (snake_case is upstream's spelling)",
    { enable_thinking: true },
    "out-of-scope fields",
  );
  reject("a non-boolean enableThinking", { enableThinking: "yes" }, "not a boolean");
  reject("tools that are not an array", { tools: {} }, "not an array");
  reject(
    "a declaration of another type",
    { tools: [{ type: "custom", function: { name: "f" } }] },
    "not 'function'",
  );
  reject(
    // `strict` is accepted since the 2026-11-04 review (it constrains the host, not the prompt).
    "an unknown declaration field (examples — the template drops it)",
    { tools: [{ type: "function", function: { name: "f", examples: [] } }] },
    "out-of-scope fields",
  );
  reject(
    "a property type list (the template would print a Python repr)",
    {
      tools: [
        {
          type: "function",
          function: {
            name: "f",
            parameters: { type: "object", properties: { a: { type: ["string", "null"] } } },
          },
        },
      ],
    },
    "not a string",
  );
  reject(
    "a non-finite number in a schema",
    {
      tools: [
        {
          type: "function",
          function: {
            name: "f",
            parameters: { type: "object", properties: { a: { enum: [Number.NaN] } } },
          },
        },
      ],
    },
    "not a finite number",
  );

  it("tool call arguments must be JSON values (undefined is not one)", () => {
    assertThrows(
      () =>
        renderGemma4Chat([
          { role: "user", content: "x" },
          {
            role: "assistant",
            content: "",
            tool_calls: [
              { type: "function", function: { name: "f", arguments: { a: undefined } as never } },
            ],
          },
          { role: "tool", name: "f", content: "ok" },
        ]),
      ModelInputError,
      "not a JSON value",
    );
  });
});

describe("pythonNumber: numbers as Python's str() prints them", () => {
  it("non-integers print as repr(float) (values measured with CPython 3.14)", () => {
    const measured: [number, string][] = [
      [0.1, "0.1"],
      [1e-5, "1e-05"],
      [0.0001, "0.0001"],
      [1.5e-7, "1.5e-07"],
      [123.456, "123.456"],
      [-2.5, "-2.5"],
      [0.30000000000000004, "0.30000000000000004"],
      [2.5e-10, "2.5e-10"],
      [5e-324, "5e-324"],
      [12345678.9, "12345678.9"],
      [-0.001, "-0.001"],
    ];
    for (const [value, expected] of measured) assertEquals(pythonNumber(value), expected, expected);
  });

  it("an integer value prints as Python's int (a JS number carries no int / float distinction)", () => {
    assertEquals(pythonNumber(2), "2");
    assertEquals(pythonNumber(-3), "-3");
    assertEquals(pythonNumber(-0), "0");
    assertEquals(pythonNumber(1e21), "1000000000000000000000");
  });
});

describe("gemma4 chat review fixes (2026-11-04): reasons, numbers, key order, readable arguments", () => {
  const source = fixture as ToolFixture;

  it("every refusal table entry names a refused row, and every refused row has one", () => {
    const refused = source.responses.filter(
      (row) => row.expect === "upstream-raises" || row.expect === "ts-rejects",
    );
    assertEquals(refused.map((row) => row.name).toSorted(), Object.keys(PARSE_REASONS).toSorted());
    assertEquals(
      source.rejectedChat.map((row) => row.name).toSorted(),
      Object.keys(REJECTION_REASONS).toSorted(),
    );
  });

  it("blank segments: upstream's own reading differs, TS keeps the earlier text", () => {
    const rows = source.responses.filter((row) => row.expect === "blank-segment");
    assertEquals(
      rows.map((row) => row.name),
      ["blank-after-call", "blank-second-thought"],
    );
    for (const row of rows) {
      assert(row.normalized !== undefined && row.upstream !== undefined, row.name);
      // TS reads the output as upstream reads it without the blank segment…
      assertEquals(
        parseGemma4ChatResponse(row.text, row.prefix),
        parseGemma4ChatResponse(row.normalized, row.prefix),
      );
    }
  });

  it("float forms come back as JS numbers and re-render as such (documented)", () => {
    const row = source.responses.find((candidate) => candidate.name === "float-forms");
    assert(row !== undefined);
    const parsed = parseGemma4ChatResponse(row.text, row.prefix);
    const [call] = parsed.tool_calls ?? [];
    assert(call !== undefined);
    assert(Object.is(call.function.arguments.b, -0), "-0.0 is -0");
    const rendered = renderGemma4Chat(
      [
        { role: "user", content: "x" },
        { role: "assistant", content: "", tool_calls: [call] },
        { role: "tool", name: "ping", content: "ok" },
      ],
      "gemma4",
    );
    // Upstream's round trip writes `a:100000.0,b:-0.0,c:2.0` — Python keeps the float type.
    assert(rendered.includes("call:ping{a:100000,b:0,c:2,d:0.5}"), rendered);
  });

  it("integer-like keys come back first (JS object order), equal as objects", () => {
    const row = source.responses.find((candidate) => candidate.name === "integer-like-keys");
    assert(row !== undefined);
    const [call] = parseGemma4ChatResponse(row.text, row.prefix).tool_calls ?? [];
    assert(call !== undefined);
    assertEquals(Object.keys(call.function.arguments), ["2", "10", "b", "a"]);
    assertEquals(call.function.arguments, row.parsed?.tool_calls?.[0].function.arguments);
  });

  it("without the reviver's source text, any integer-valued number beyond 2^53 is refused (never rounded)", () => {
    const original = JSON.parse;
    // A runtime without "JSON.parse source text access": the reviver gets no context.
    JSON.parse = ((
      text: string,
      reviver?: (this: unknown, key: string, value: unknown) => unknown,
    ) =>
      original(
        text,
        reviver === undefined
          ? undefined
          : function (this: unknown, key: string, value: unknown): unknown {
              return reviver.call(this, key, value);
            },
      )) as typeof JSON.parse;
    try {
      const prefix = "<|turn>model\n";
      const call = (body: string): string =>
        `<|tool_call>call:f{${body}}<tool_call|><|tool_response>`;
      assertThrows(
        () => parseGemma4ChatResponse(call("n:1e20"), prefix),
        ModelInputError,
        "does not pass the number's source text",
      );
      assertThrows(
        () => parseGemma4ChatResponse(call("n:9007199254740993"), prefix),
        ModelInputError,
        "beyond 2^53",
      );
      assertEquals(
        parseGemma4ChatResponse(call("n:12,m:0.5"), prefix).tool_calls?.[0].function.arguments,
        {
          n: 12,
          m: 0.5,
        },
      );
    } finally {
      JSON.parse = original;
    }
    // With the source text, a float literal beyond 2^53 is a float, not a rounded integer.
    assertEquals(
      parseGemma4ChatResponse(
        "<|tool_call>call:f{n:1e20}<tool_call|><|tool_response>",
        "<|turn>model\n",
      ).tool_calls?.[0].function.arguments,
      { n: 1e20 },
    );
  });

  it("an empty prompt is upstream's opt-out (no anchor needed)", () => {
    assertEquals(parseGemma4ChatResponse("Sunny.<turn|>", ""), {
      role: "assistant",
      content: "Sunny.",
    });
  });

  it("a thought channel the prompt opened says so when it is left open", () => {
    assertThrows(
      () => parseGemma4ChatResponse("still thinking", "<tool_response|><|channel>thought\n"),
      ModelInputError,
      "opened by the prompt's prefill",
    );
  });

  it("a sparse array in arguments fails loudly (a hole would render as [1,,2])", () => {
    // oxlint-disable-next-line no-sparse-arrays -- the hole is the input under test
    const holed = [1, , 2] as unknown as ChatJsonValue;
    assertThrows(
      () =>
        renderGemma4Chat([
          { role: "user", content: "x" },
          {
            role: "assistant",
            content: "",
            tool_calls: [{ type: "function", function: { name: "f", arguments: { a: holed } } }],
          },
          { role: "tool", name: "f", content: "ok" },
        ]),
      ModelInputError,
      "hole of a sparse array",
    );
  });

  it("an argument string holding the call's closer is refused like the delimiter", () => {
    assertThrows(
      () =>
        renderGemma4Chat([
          { role: "user", content: "x" },
          {
            role: "assistant",
            content: "",
            tool_calls: [
              { type: "function", function: { name: "f", arguments: { a: ["x<tool_call|>y"] } } },
            ],
          },
          { role: "tool", name: "f", content: "ok" },
        ]),
      ModelInputError,
      "<tool_call|>, which the rendered call cannot delimit",
    );
  });

  it("a non-boolean strict and a non-number index are still refused", () => {
    const user: ChatMessage[] = [{ role: "user", content: "x" }];
    assertThrows(
      () =>
        renderGemma4Chat(user, "gemma4", {
          tools: [{ function: { name: "f", strict: "yes" as unknown as boolean } }],
        }),
      ModelInputError,
      "strict is not a boolean",
    );
    assertThrows(
      () =>
        renderGemma4Chat([
          ...user,
          {
            role: "assistant",
            content: "",
            tool_calls: [
              { index: "0" as unknown as number, function: { name: "f", arguments: {} } },
            ],
          },
          { role: "tool", name: "f", content: "ok" },
        ]),
      ModelInputError,
      "index is not a number",
    );
  });
});

// ---- Pipeline.chat without maxNewTokens --------------------------------------------------
//
// The real `chat` on the real sequence, with only the Session faked: the fake keeps the logical
// length, and its logits are widened to the vocabulary the fixture's chat prompt needs.

describe("Pipeline.chat without maxNewTokens generates until a stop token or the limit", () => {
  const MESSAGES: readonly ChatMessage[] = [{ role: "user", content: "Name a color." }];
  const PROMPT_LENGTH = chatPrompt(tokenizer, MESSAGES).length;
  const VOCABULARY = 262144;
  const ANSWER = tokenizer.encode("Blue")[0];

  /** Exposes the constructor the two public subclasses keep closed. */
  class SeatedPipeline extends GemmaPipeline {
    constructor(state: Gemma4State) {
      super(state);
    }
  }

  /** A pipeline whose default capacity leaves room for `room` tokens after the prompt. */
  const seated = (room: number, stopTokens: readonly number[] = []) => {
    const fake = fakeSession();
    const session: typeof fake.session = {
      ...fake.session,
      run: async (inputs, bindings, generation) => {
        await fake.session.run(inputs, bindings, generation);
        const data = new Float32Array(VOCABULARY);
        data[ANSWER] = 10;
        return { [LOGITS]: { dtype: "f32", shape: [1, 1, VOCABULARY], data } };
      },
    };
    const wiring = {
      ...programOf(fake, { capacity: PROMPT_LENGTH + room - 1 }),
      vocabSize: VOCABULARY,
      stopTokens,
    };
    // Only what `chat` reads: a real state holds a GPU Session this check has no use for.
    const state = {
      entry: "test.Pipeline",
      session,
      wiring,
      tokenizer,
      config: {},
    } as unknown as Gemma4State;
    return { fake, pipeline: new SeatedPipeline(state) };
  };

  it("runs to the limit and reports capacity", async () => {
    const { fake, pipeline } = seated(3);
    const stream = pipeline.chat(MESSAGES, {});
    assertEquals(await stream.text(), tokenizer.decode([ANSWER, ANSWER, ANSWER]));
    assertEquals(await stream.done, { reason: "capacity", tokens: 3 });
    assert(fake.calls.every((call) => call.pastBefore + call.queryLength <= PROMPT_LENGTH + 2));
  });

  it("stops at a stop token first", async () => {
    const { pipeline } = seated(3, [ANSWER]);
    const stream = pipeline.chat(MESSAGES, {});
    assertEquals(await stream.text(), "");
    assertEquals(await stream.done, { reason: "eos", token: ANSWER, tokens: 1 });
  });

  it("forwards a value that is present (an explicit limit closes as max-tokens)", async () => {
    const { pipeline } = seated(3);
    const stream = pipeline.chat(MESSAGES, { maxNewTokens: 3 });
    await stream.text();
    assertEquals(await stream.done, { reason: "max-tokens", tokens: 3 });
  });

  it("an invalid value still fails at the call", () => {
    const { pipeline } = seated(3);
    for (const maxNewTokens of [0, Number.NaN, null as unknown as number]) {
      assertThrows(
        () => pipeline.chat(MESSAGES, { maxNewTokens }),
        ModelInputError,
        "is not a positive integer",
      );
    }
  });

  it("a prompt that alone does not fit fails with GenerationCapacityError before any run", async () => {
    const { fake, pipeline } = seated(0);
    await assertRejects(() => pipeline.chat(MESSAGES, {}).text(), GenerationCapacityError);
    assertEquals(fake.calls.length, 0);
  });
});
